)
func main() {
 for _,checkedFirst:=range []bool{false,true} {
 source:="namespace N { export const own = 1; } const extra = 2; const enum E { A }"
 fs:=vfstest.FromMap(map[string]string{"/main.ts":source,"/tsconfig.json":`{"compilerOptions":{"strict":true,"singleThreaded":true,"noEmit":true,"target":"es2020"},"files":["main.ts"]}`},true)
 host:=compiler.NewCompilerHost("/",bundled.WrapFS(fs),bundled.LibPath(),nil,nil)
 config,errs:=tsoptions.GetParsedCommandLineOfConfigFile("/tsconfig.json",&core.CompilerOptions{},nil,host,nil);if len(errs)!=0 {panic(errs)}
 program:=compiler.NewProgram(compiler.ProgramOptions{Config:config,Host:host});program.BindSourceFiles()
 c,done:=program.GetTypeChecker(context.Background())
 file:=program.GetSourceFile("/main.ts")
 if checkedFirst {if d:=c.GetDiagnostics(context.Background(),file);len(d)!=0 {panic(d)}}
 rows:=[]any{}
 for i:=0;i<2;i++ {
 r:=c.QualifyRawOwners(file)
 if r.RawExports!=1||r.CopyExports!=1||r.TwinExports!=1||r.ExtendedExports!=2||!r.RawUnredirected||!r.CopyHasAddedEdge||r.RawHasAddedEdge||r.TwinHasAddedEdge||!r.RawConstEnum||!r.CopyConstEnum||!r.MemberParentIsRaw||r.MemberParentIsCopy {panic(fmt.Sprintf("unexpected raw owner control: %+v",r))}
 rows=append(rows,r)
 }
 if d:=c.GetDiagnostics(context.Background(),file);len(d)!=0 {panic(d)}
 out,err:=json.Marshal(map[string]any{"checkedFirst":checkedFirst,"rows":rows});if err!=nil {panic(err)};fmt.Println(string(out));done()
 }
}

