 config,errs:=tsoptions.GetParsedCommandLineOfConfigFile("/tsconfig.json",&core.CompilerOptions{},nil,host,nil);if len(errs)!=0 {panic(errs)}
 program:=compiler.NewProgram(compiler.ProgramOptions{Config:config,Host:host});program.BindSourceFiles()
 c,done:=program.GetTypeChecker(context.Background())
 file:=program.GetSourceFile("/main.ts")
 if checkedFirst {if d:=c.GetDiagnostics(context.Background(),file);len(d)!=0 {panic(d)}}
 rows:=[]any{}
 for i:=0;i<1;i++ {
