 if !r.DistinctCopies||!r.RawUnredirected||len(r.Pushes)!=4||!r.Pushes[0]||!r.Pushes[1]||!r.Pushes[2]||r.Pushes[3]||r.OtherPropertyCycleIndex!=-1||r.DepthAfterCycle!=3||len(r.Pops)!=3||r.Pops[0]||r.Pops[1]||!r.Pops[2]||!r.BoundValuePublished||r.HeadValuePublished||r.TwinValuePublished||!r.BoundDeclaredPublished||r.HeadDeclaredPublished||r.TwinDeclaredPublished {panic(fmt.Sprintf("unexpected symbol key control: %+v",r))}
