+                checker.check_source_file(
+                    root,
+                    crate::check::FileContext { ambient: false, has_parse_errors: false },
+                );
+            }
+            let owner = checker.symbols.bound(bound.lookup_local(root, "Plain").unwrap()).unwrap();
+            let copy = checker.symbols.clone_module_symbol(&owner).unwrap();
+            assert_eq!(checker.private_names_of_anonymous_symbol_are_complete(&owner), Ok(true));
+            assert_eq!(checker.private_names_of_anonymous_symbol_are_complete(&copy), Ok(true));
