+mod tests {
+    use crate::Checker;
+
+    #[test]
+    fn raw_owner_bound_private_name_completeness_cases() {
+        let source = "class Plain {} class Generic<T> {} class Based extends Plain {} namespace N { export const x = 1; } const enum E { A } function f() {}";
+        let arena = tsr_core::Arena::new();
+        let parsed = tsr_parser::parse(&arena, source);
+        assert!(parsed.diagnostics.is_empty());
+        let root = parsed.source_file.node_id.unwrap();
+        let bound = tsr_binder::bind(
+            &arena,
+            parsed.source_file,
+            &parsed.nodes,
+            tsr_binder::FileInfo { name: "raw-owner.ts", text: source },
+        );
+        let mut checker = Checker::new(&bound, &parsed.nodes, &parsed.node_map);
+        for (name, expected) in [
+            ("Plain", true),
+            ("Generic", true),
+            ("Based", true),
+            ("N", false),
+            ("E", false),
+            ("f", false),
+        ] {
+            let ty = checker.get_type_of_symbol(bound.lookup_local(root, name).unwrap());
+            assert_eq!(checker.private_names_are_complete(ty), expected, "{name}");
+        }
+    }
+
+    #[test]
+    fn raw_owner_private_name_completeness_reads_private_declarations() {
+        for checked_first in [false, true] {
+            let source = "class Plain {} function f() {}";
+            let arena = tsr_core::Arena::new();
+            let parsed = tsr_parser::parse(&arena, source);
+            let root = parsed.source_file.node_id.unwrap();
+            let bound = tsr_binder::bind(
+                &arena,
+                parsed.source_file,
+                &parsed.nodes,
+                tsr_binder::FileInfo { name: "raw-owner.ts", text: source },
+            );
+            let mut checker = Checker::new(&bound, &parsed.nodes, &parsed.node_map);
+            if checked_first {
+                checker.check_source_file(
+                    root,
+                    crate::check::FileContext { ambient: false, has_parse_errors: false },
+                );
+            }
+            let owner = checker.symbols.bound(bound.lookup_local(root, "Plain").unwrap()).unwrap();
+            let copy = checker.symbols.clone_module_symbol(&owner).unwrap();
+            assert_eq!(checker.private_names_of_anonymous_symbol_are_complete(&owner), Ok(true));
+            assert_eq!(checker.private_names_of_anonymous_symbol_are_complete(&copy), Ok(true));
+            let function = bound.lookup_local(root, "f").unwrap();
+            checker
+                .symbols
+                .append_declaration(&copy, bound.symbols().get(function).declarations[0])
+                .unwrap();
+            assert_eq!(checker.private_names_of_anonymous_symbol_are_complete(&copy), Ok(false));
+            assert_eq!(checker.private_names_of_anonymous_symbol_are_complete(&owner), Ok(true));
